import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../app/app_providers.dart';

class BusinessHoursScreen extends ConsumerStatefulWidget { const BusinessHoursScreen({super.key}); @override ConsumerState<BusinessHoursScreen> createState()=>_BusinessHoursScreenState(); }
class _BusinessHoursScreenState extends ConsumerState<BusinessHoursScreen> {
  static const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  final open=List<bool>.filled(7,false); final from=List.generate(7,(_)=>TextEditingController()); final to=List.generate(7,(_)=>TextEditingController()); final timezone=TextEditingController(text:'Africa/Johannesburg'); bool busy=true;
  @override void initState(){super.initState(); _load();}
  String _time(dynamic value) { final text='${value ?? ''}'; return text.length >= 5 ? text.substring(0,5) : text; }
  Future<void> _load() async { final w=ref.read(workspaceControllerProvider).value; if(w==null)return; final rows=await ref.read(businessBrainRepositoryProvider).list('business_hours',w.id,orderBy:'weekday'); for(final row in rows){final i=(row['weekday'] as int)-1; if(i>=0&&i<7){open[i]=row['is_open']==true; from[i].text=_time(row['opens_at']); to[i].text=_time(row['closes_at']); timezone.text='${row['timezone']??timezone.text}';}} if(mounted)setState(()=>busy=false); }
  Future<void> _save() async { final w=ref.read(workspaceControllerProvider).value; if(w==null)return; for(var i=0;i<7;i++){if(open[i]&&(from[i].text.isEmpty||to[i].text.isEmpty||from[i].text.compareTo(to[i].text)>=0)){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('${days[i]} needs opening and closing times in order.')));return;} await ref.read(businessBrainRepositoryProvider).save('business_hours',w.id,{'weekday':i+1,'is_open':open[i],'opens_at':open[i]?from[i].text:null,'closes_at':open[i]?to[i].text:null,'timezone':timezone.text.trim()});} if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Business hours saved.'))); }
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Business Hours'),actions:[IconButton(onPressed:_save,icon:const Icon(Icons.save))]),body:busy?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:timezone,decoration:const InputDecoration(labelText:'Timezone')),const SizedBox(height:12),...List.generate(7,(i)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Text(days[i])),Switch(value:open[i],onChanged:(v)=>setState(()=>open[i]=v)),SizedBox(width:90,child:TextField(controller:from[i],enabled:open[i],decoration:const InputDecoration(labelText:'Open'),keyboardType:TextInputType.datetime)),const SizedBox(width:8),SizedBox(width:90,child:TextField(controller:to[i],enabled:open[i],decoration:const InputDecoration(labelText:'Close'),keyboardType:TextInputType.datetime))]))),)]));
}
